{"source_family": "OpenRA/OpenRA", "revision": "b4d95a56717d8d0070f195e343f6c2728ce87900", "license": "GPL-3.0 publicsource,license/fileheadersretained; internalresearchonly,nopublication/training", "topic": "Selected Actor disposal and World frame-end queue lifecycle, not entire engine", "source_cards": [{"id": "OA0-type", "path": "OpenRA.Game/Actor.cs", "lines": [36, 36], "selection": "Actor declared interfaces", "source_sha256": "f871fc13f30ebd804328814992d44001218a33c0cc3c267a60668d3409af70f2", "quote": "	public sealed class Actor : IScriptBindable, IScriptNotifyBind, ILuaTableBinding, ILuaEqualityBinding, ILuaToStringBinding, IEquatable<Actor>, IDisposable", "quote_sha256": "dfd4dbb92d1f2a79706efd29903cc40c88f878b1110d2371a5b47c5e87b1552c"}, {"id": "OA0-world", "path": "OpenRA.Game/Actor.cs", "lines": [49, 53], "selection": "Actor readonly World and identity fields", "source_sha256": "f871fc13f30ebd804328814992d44001218a33c0cc3c267a60668d3409af70f2", "quote": "		public readonly ActorInfo Info;

		public readonly World World;

		public readonly uint ActorID;", "quote_sha256": "2a24de4f4b04e31bee5f8eb7cc89b14dca5e64390f53dd884c5c76cb1a7a4c4b"}, {"id": "OA1", "path": "OpenRA.Game/Actor.cs", "lines": [57, 66], "selection": "Actor flags and CurrentActivity property", "source_sha256": "f871fc13f30ebd804328814992d44001218a33c0cc3c267a60668d3409af70f2", "quote": "		public bool IsInWorld { get; internal set; }
		public bool WillDispose { get; private set; }
		public bool Disposed { get; private set; }

		Activity currentActivity;
		public Activity CurrentActivity
		{
			get => Activity.SkipDoneActivities(currentActivity);
			private set => currentActivity = value;
		}", "quote_sha256": "4cc3e1d8f317772754de1dc7e994766a33a1f2d2db36ecd9890eb0bca7138cb0"}, {"id": "OA2", "path": "OpenRA.Game/Actor.cs", "lines": [409, 412], "selection": "Trait interface lookup delegation", "source_sha256": "f871fc13f30ebd804328814992d44001218a33c0cc3c267a60668d3409af70f2", "quote": "		public IEnumerable<T> TraitsImplementing<T>()
		{
			return World.TraitDict.WithInterface<T>(this);
		}", "quote_sha256": "cffe485c15cdd25ca9356c7557e76f7837e07254614f9e19b549182fa694bbd7"}, {"id": "OA3", "path": "OpenRA.Game/Actor.cs", "lines": [419, 444], "selection": "Complete Actor.Dispose declaration", "source_sha256": "f871fc13f30ebd804328814992d44001218a33c0cc3c267a60668d3409af70f2", "quote": "		public void Dispose()
		{
			// If CurrentActivity isn't null, run OnActorDisposeOuter in case some cleanups are needed.
			// This should be done before the FrameEndTask to avoid dependency issues.
			CurrentActivity?.OnActorDisposeOuter(this);

			// Allow traits/activities to prevent a race condition when they depend on disposing the actor (e.g. Transforms)
			WillDispose = true;

			World.AddFrameEndTask(w =>
			{
				if (Disposed)
					return;

				if (IsInWorld)
					World.Remove(this);

				foreach (var t in TraitsImplementing<INotifyActorDisposing>())
					t.Disposing(this);

				World.TraitDict.RemoveActor(this);
				Disposed = true;

				luaInterface?.Value.OnActorDestroyed();
			});
		}", "quote_sha256": "5efc763ecb8ffc653ca77921ac90443112741d20e4de60426e57b27c22534d3b"}, {"id": "OA4", "path": "OpenRA.Game/World.cs", "lines": [40, 40], "selection": "Frame-end queue field", "source_sha256": "3ef7573b518cfbb78d375d0ede8c16fe0a45220fcc68e5bb15673926e1406f73", "quote": "		readonly Queue<Action<World>> frameEndActions = [];", "quote_sha256": "886f10fceea48c5333e4899847536bdc7c768a8be47e4aae72414bccd595cf83"}, {"id": "OA5", "path": "OpenRA.Game/World.cs", "lines": [383, 383], "selection": "Complete AddFrameEndTask declaration", "source_sha256": "3ef7573b518cfbb78d375d0ede8c16fe0a45220fcc68e5bb15673926e1406f73", "quote": "		public void AddFrameEndTask(Action<World> a) { frameEndActions.Enqueue(a); }", "quote_sha256": "021c2929d49bd07c4e37ae9f52f4572e2ac9b42b21f3453e05084488ea46b782"}, {"id": "OA6", "path": "OpenRA.Game/World.cs", "lines": [344, 352], "selection": "Complete World.Remove(Actor) declaration", "source_sha256": "3ef7573b518cfbb78d375d0ede8c16fe0a45220fcc68e5bb15673926e1406f73", "quote": "		public void Remove(Actor a)
		{
			a.IsInWorld = false;
			actors.Remove(a.ActorID);
			ActorRemoved(a);

			foreach (var t in a.TraitsImplementing<INotifyRemovedFromWorld>())
				t.RemovedFromWorld(a);
		}", "quote_sha256": "31624e03e7c3381f18b5908769e3d7229e7c3a51fe3aa36ab55ee985448431ab"}, {"id": "OA7", "path": "OpenRA.Game/World.cs", "lines": [413, 455], "selection": "Complete World.Tick declaration", "source_sha256": "3ef7573b518cfbb78d375d0ede8c16fe0a45220fcc68e5bb15673926e1406f73", "quote": "		public void Tick()
		{
			if (wasLoadingGameSave && !IsLoadingGameSave)
			{
				foreach (var kv in gameSaveTraitData)
				{
					var tp = TraitDict.ActorsWithTrait<IGameSaveTraitData>()
						.Skip(kv.Key)
						.FirstOrDefault();

					if (tp.Actor == null)
						break;

					tp.Trait.ResolveTraitData(tp.Actor, kv.Value);
				}

				gameSaveTraitData.Clear();

				Game.Sound.DisableAllSounds = false;
				foreach (var nsr in WorldActor.TraitsImplementing<INotifyGameLoaded>())
					nsr.GameLoaded(this);

				wasLoadingGameSave = false;
			}

			// Allow users to pause the shellmap via the settings menu
			// Some traits initialize important state during the first tick, so we must allow it to tick at least once
			if (!Paused && (Type != WorldType.Shellmap || !gameSettings.PauseShellmap || WorldTick == 0))
			{
				WorldTick++;

				using (new PerfSample("tick_actors"))
					foreach (var a in actors.Values)
						a.Tick();

				ApplyToActorsWithTraitTimed<ITick>((actor, trait) => trait.Tick(actor), "Trait");

				effects.DoTimed(e => e.Tick(this), "Effect");
			}

			while (frameEndActions.Count != 0)
				frameEndActions.Dequeue()(this);
		}", "quote_sha256": "9194d5284d874e1df2d4c4bacdbbbda77bc440282f7e476ae3a18e6dbb4a3f52"}, {"id": "OA8", "path": "OpenRA.Game/World.cs", "lines": [589, 619], "selection": "Complete World.Dispose declaration", "source_sha256": "3ef7573b518cfbb78d375d0ede8c16fe0a45220fcc68e5bb15673926e1406f73", "quote": "		public void Dispose()
		{
			Disposing = true;

			OrderGenerator?.Deactivate();

			frameEndActions.Clear();

			Game.Sound.StopAudio();
			Game.Sound.StopVideo();
			if (IsLoadingGameSave)
				Game.Sound.DisableAllSounds = false;

			// Dispose newer actors first, and the world actor last
			foreach (var a in actors.Values.Reverse())
				a.Dispose();

			// Actor disposals are done in a FrameEndTask
			while (frameEndActions.Count != 0)
				frameEndActions.Dequeue()(this);

			// HACK: The shellmap OrderManager is owned by its world in order to avoid
			// problems with having multiple OMs active when joining a game lobby from the main menu.
			// A matching check in Game.JoinInner handles OM disposal for all other cases.
			if (Type == WorldType.Shellmap)
				OrderManager.Dispose();

			Map.Dispose();

			Game.FinishBenchmark();
		}", "quote_sha256": "9273e01a1731dc9d4978dd4a45d4ae83af1634f5358856a99561eaa9b8ba3b78"}, {"id": "OA9", "path": "OpenRA.Game/Traits/TraitsInterfaces.cs", "lines": [162, 163], "selection": "Disposing trait notification interface", "source_sha256": "8d7a0ba7ec134228cd626caa2e3aafadefb60b348364bb6ff8bbcaee46ead90d", "quote": "	[RequireExplicitImplementation]
	public interface INotifyActorDisposing { void Disposing(Actor self); }", "quote_sha256": "f0619a32528fad31feba819589d58e72e70fffd698dae35e75477cc1dfe7a269"}], "reviewed_source_facts": [{"id": "OF0", "evidence": ["OA0-type", "OA0-world"], "meaning": "Actor declares IDisposable among its interfaces and has public readonly World World. Selected Actor method World references concern that field; valid constructed instance assumptions remain, not general null-safety or global static lifecycle."}, {"id": "OF1", "evidence": ["OA1", "OA3"], "meaning": "WillDispose and Disposed are distinct. Actor.Dispose first invokes CurrentActivity?.OnActorDisposeOuter(this); only if control proceeds does it set WillDispose=true and enqueue. There is no whole-method early Disposed guard. Do not promise entire Dispose is idempotent or thread-safe."}, {"id": "OF2", "evidence": ["OA3"], "meaning": "The queued lambda checks Disposed and returns if already true. Otherwise it conditionally calls World.Remove(this) when IsInWorld, invokes Disposing on selected INotifyActorDisposing traits, calls World.TraitDict.RemoveActor(this), sets Disposed=true, then invokes luaInterface?.Value.OnActorDestroyed(). Written order depends on prior operations returning normally."}, {"id": "OF3", "evidence": ["OA2", "OA9"], "meaning": "TraitsImplementing<T> delegates to World.TraitDict.WithInterface<T>(this). INotifyActorDisposing declares Disposing(Actor self). Internal lookup/removal and concrete callbacks are dependencies not fully verified by this selection."}, {"id": "OF4", "evidence": ["OA6"], "meaning": "World.Remove(Actor) sets IsInWorld=false, removes ActorID from actors, invokes ActorRemoved, then notifies INotifyRemovedFromWorld traits. No guarantee all notifications complete if a callback throws."}, {"id": "OF5", "evidence": ["OA4", "OA5"], "meaning": "frameEndActions is declared Queue<Action<World>>. AddFrameEndTask only enqueues its action; it does not execute it. There is no explicit locking or generic cleanup guarantee in this selected declaration."}, {"id": "OF6", "evidence": ["OA7"], "meaning": "World.Tick has a Paused/shellmap condition around actor/trait/effect update work. The while(frameEndActions.Count != 0) Dequeue()(this) loop is outside that condition. If Tick reaches the loop, pause alone does not skip it; this does not guarantee Tick is called or callbacks finish."}, {"id": "OF7", "evidence": ["OA7", "OA8"], "meaning": "The loop tests the live queue count each iteration, not a frozen snapshot. New tasks enqueued by callbacks can be processed before that drain ends if execution continues. No promised next-frame-only timing, termination, exception recovery or universal task completion."}, {"id": "OF8", "evidence": ["OA8"], "meaning": "World.Dispose sets Disposing=true, deactivates the order generator if present, and clears already queued frame-end work before calling a.Dispose() over actors.Values.Reverse(). It then drains newly queued tasks, conditionally disposes the shellmap OrderManager, disposes Map and finishes benchmark. This differs from guaranteeing every earlier queued task runs."}, {"id": "OF9", "evidence": ["OA3", "OA7", "OA8"], "meaning": "Selected callback and drain paths have no explicit exception recovery/finally that guarantees all remaining disposal operations. Flag comments about race prevention do not establish synchronization. No source or game program was executed."}, {"id": "OF10", "evidence": [], "meaning": "Repository test path metadata includes ActionQueueTest.cs and ActorInfoTest.cs. No direct actor/frame-end lifecycle test body or passing result is supplied here. State that limit; do not invent test names/coverage/results. Use a short exact source fragment as an example, explicitly not a complete compiled/run program. No full engine, game loop caller, trait dictionary or activity/Lua dependency contract is proven."}], "required_FAQ": [{"id": "OQ1", "en": "Does Actor.Dispose immediately set Disposed=true or make every repeated call a complete no-op?", "pt-BR": "Actor.Dispose define Disposed=true imediatamente ou torna toda chamada repetida uma operação totalmente sem efeito?"}, {"id": "OQ2", "en": "Does Paused by itself prevent World.Tick from draining frame-end tasks?", "pt-BR": "Paused, por si só, impede World.Tick de processar a fila de fim de frame?"}, {"id": "OQ3", "en": "Does World.Dispose guarantee execution of tasks queued before it started?", "pt-BR": "World.Dispose garante a execução de tarefas enfileiradas antes de começar?"}], "scope_limits": "Source-only. No game/runtime/test/build executed; no directlifecycle testbodyorpassingresults provided. Helpers/activity/traitdictionary/Luainternals unverified. Existing source/docs unchanged."}
